import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, add, mul, fract, sin, dot, float, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // ---------- Backdrop Plane with Gradient & Grain ----------
  const planeGeo = new THREE.PlaneGeometry(7, 5.5);
  const gradMat = new MeshBasicNodeMaterial();

  const topCol = new THREE.Color('#0b0b10');
  const botCol = new THREE.Color('#14141a');

  const topVec = vec3(topCol.r, topCol.g, topCol.b);
  const botVec = vec3(botCol.r, botCol.g, botCol.b);

  const baseColor = mix(topVec, botVec, uv().y);

  // monochrome grain ~1.5%
  const grain = mul(
    fract(sin(dot(uv(), vec3(12.9898, 78.233, 0.0))) * 43758.5453),
    float(0.015)
  );

  gradMat.colorNode = add(baseColor, grain);
  const planeMesh = new THREE.Mesh(planeGeo, gradMat);
  planeMesh.position.set(0, 0, 0);
  group.add(planeMesh);

  // ---------- Text Content ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Mapping of vertical positions (scene units) per spec order
  const yPositions = [1.7, 0.9, 0.25, -0.8, -1.9]; // kicker, hero1, hero2, body, caption
  const textObjects = [];

  items.forEach((item, idx) => {
    const opts = {
      fontSize: item.typography?.fontSize ?? 24,
      color: config.visualSpec?.colors?.ink ?? '#16161d',
      align: 'left',
      maxWidthPx: undefined,
      letterSpacingPx: undefined,
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    txt.position.set(-3.1, yPositions[idx] ?? 0, 0);
    group.add(txt);
    textObjects.push(txt);
  });

  // ---------- Hero Letterpress Shadow (duplicate behind) ----------
  const heroIndices = [1, 2]; // indices of hero lines in items array
  heroIndices.forEach((i) => {
    const orig = textObjects[i];
    if (!orig) return;
    const shadow = orig.clone();
    shadow.position.z = -0.02;
    // Assuming the text object has a material with a color property
    if (shadow.material && shadow.material.color) {
      shadow.material.color.set('#16161d');
    }
    group.add(shadow);
  });

  // ---------- Accent Underline Rule ----------
  const underlineGeo = new THREE.PlaneGeometry(2.2, 0.05);
  const underlineMat = new MeshStandardNodeMaterial({
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 1.2,
    metalness: 0,
    roughness: 1,
    transparent: true,
    opacity: 1,
  });
  const underline = new THREE.Mesh(underlineGeo, underlineMat);
  underline.position.set(-3.1 + 1.1, -0.15, 0); // left-aligned start at -3.1, centered width
  underline.scale.set(0, 1, 1); // start collapsed horizontally
  group.add(underline);

  // ---------- GSAP Animations ----------
  const timelines = [];

  // Prepare initial states
  const blocks = [...textObjects, underline];
  blocks.forEach((obj) => {
    obj.position.y += 0.4;
    if (obj.material && obj.material.opacity !== undefined) {
      obj.material.transparent = true;
      obj.material.opacity = 0;
    }
  });

  const tl = gsap.timeline();
  timelines.push(tl);

  // Rise‑in for text blocks (stagger 80 ms)
  tl.from(
    textObjects,
    {
      y: '+=0.4',
      opacity: 0,
      duration: 0.7,
      ease: 'power3.out',
      stagger: 0.08,
    },
    0
  );

  // Underline draw after hero lands (after third text block)
  tl.from(
    underline.scale,
    {
      x: 0,
      duration: 0.5,
      ease: 'power1.out',
    },
    '+=0.2'
  );

  // ---------- Cleanup ----------
  group.userData.cleanup = () => {
    // Dispose geometry & materials
    planeGeo.dispose();
    gradMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();

    // Dispose any textures used by materials (none here)

    // Kill GSAP timelines
    timelines.forEach((t) => t.kill());

    // Dispose text objects if they have disposables
    textObjects.forEach((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
    });
  };

  // No interaction handlers required for this node
  group.userData.handlers = {};

  return group;
}
